package dev.almaz.pathway.web;
import dev.almaz.pathway.data.ApplicationRepository;import dev.almaz.pathway.domain.Application;import org.springframework.web.bind.annotation.*;import org.springframework.validation.annotation.Validated;import jakarta.validation.Valid;import java.util.*;
@RestController @RequestMapping("/api/applications") @Validated public class ApplicationController{private final ApplicationRepository repo;public ApplicationController(ApplicationRepository r){repo=r;} @GetMapping public List<Application> list(){return repo.findByOwnerOrderByIdDesc("demo");} @PostMapping public Application create(@RequestBody @Valid Application value){value.setOwner("demo");return repo.save(value);} @DeleteMapping("/{id}") public void delete(@PathVariable Long id){repo.deleteById(id);}}
